"""Telegram Mini App — the client's live trading terminal inside Telegram.

Served by the bot's own HTTP server at /app. The page authenticates itself by
sending Telegram's signed initData with every API call; validate() checks the
HMAC per https://core.telegram.org/bots/webapps#validating-data-received so a
client can only ever see THEIR OWN account."""
import hmac
import json
import hashlib
from urllib.parse import parse_qsl


def validate(init_data: str, bot_token: str):
    """Return the Telegram user dict if initData is authentic, else None."""
    try:
        pairs = dict(parse_qsl(init_data, keep_blank_values=True))
        their_hash = pairs.pop("hash", "")
        dcs = "\n".join(f"{k}={v}" for k, v in sorted(pairs.items()))
        secret = hmac.new(b"WebAppData", bot_token.encode(), hashlib.sha256).digest()
        calc = hmac.new(secret, dcs.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(calc, their_hash):
            return None
        return json.loads(pairs.get("user", "{}"))
    except Exception:
        return None


HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">\n<title>Apex Terminal</title>\n<style>\n:root{--bg:#07090f;--card:rgba(255,255,255,.045);--line:rgba(255,255,255,.08);\n  --t0:#eef1f6;--t1:#9aa3b2;--t2:#5b6472;--up:#2fd575;--dn:#ff4560;--acc:#ff2d4f;--gold:#f5b544}\n*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nbody{background:var(--bg);color:var(--t0);font-family:-apple-system,\'SF Pro Display\',system-ui,sans-serif;\n  overflow-x:hidden;padding-bottom:30px}\nbody::before{content:\'\';position:fixed;inset:0;pointer-events:none;z-index:0;\n  background:radial-gradient(70% 32% at 50% -4%,rgba(255,45,79,.16),transparent 70%)}\n.wrap{position:relative;z-index:1}\n@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n.rise{animation:rise .5s cubic-bezier(.22,.61,.36,1) both}\n/* HERO */\n#hero{padding:18px 16px 14px}\n#brand{font-size:10.5px;font-weight:800;letter-spacing:.28em;color:var(--t2);margin-bottom:10px}\n#brand b{color:var(--acc)}\n#statusLine{font-size:14.5px;font-weight:600;color:var(--t1);margin-bottom:14px;line-height:1.4}\n#statusLine b{color:var(--t0);font-weight:800}\n#balRow{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}\n#balV{font-size:34px;font-weight:800;letter-spacing:-.02em;font-variant-numeric:tabular-nums}\n#dayChip{font-size:13px;font-weight:700;border-radius:9px;padding:6px 10px;background:rgba(47,213,117,.12);color:var(--up)}\n#dayChip.neg{background:rgba(255,69,96,.12);color:var(--dn)}\n#balV{transition:color .35s ease-out}#balV.up{color:var(--up)}#balV.dn{color:var(--dn)}\n#badges{margin-top:10px;font-size:12.5px;color:var(--t1);font-weight:600}\n/* STAT TILES */\n#tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:4px 16px 0}\n.tile{background:linear-gradient(165deg,rgba(255,255,255,.06),rgba(255,255,255,.02));\n  border:1px solid var(--line);border-radius:14px;padding:10px 8px;text-align:center;backdrop-filter:blur(12px)}\n.tile b{display:block;font-size:15.5px;font-weight:800;font-variant-numeric:tabular-nums}\n.tile span{display:block;font-size:8.5px;font-weight:700;letter-spacing:.09em;color:var(--t2);\n  text-transform:uppercase;margin-top:3px}\n/* CHART CARD */\n.card{margin:12px 16px 0;background:linear-gradient(165deg,rgba(255,255,255,.05),rgba(255,255,255,.015));\n  border:1px solid var(--line);border-radius:18px;overflow:hidden;backdrop-filter:blur(14px)}\n.card-h{display:flex;align-items:center;justify-content:space-between;padding:12px 14px 8px}\n.card-h b{font-size:13.5px;font-weight:800}\n.card-h span{font-size:10.5px;color:var(--t2);font-weight:600}\n#chart{height:42vh}\n#eqChart{height:30vh;display:none}\n#pos{margin:10px 14px 12px;padding:11px 12px;border:1px solid var(--line);border-radius:12px;\n  font-size:13px;display:none;background:rgba(0,0,0,.25)}\n#pos .lg{font-weight:800}\n#pos .grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-top:8px;font-size:11.5px;color:var(--t1)}\n#pos .grid b{display:block;color:var(--t0);font-size:12.5px;font-variant-numeric:tabular-nums}\n.pnl-up{color:var(--up)} .pnl-dn{color:var(--dn)}\n/* TABS */\n#tabs{display:flex;gap:6px;margin:14px 16px 10px}\n.tab{flex:1;text-align:center;padding:10px 4px;background:var(--card);border:1px solid var(--line);\n  border-radius:12px;font-size:11.5px;font-weight:700;color:var(--t1);transition:all .25s;backdrop-filter:blur(10px)}\n.tab.on{color:#fff;border-color:rgba(255,45,79,.45);background:rgba(255,45,79,.13)}\n.panel{margin:0 16px;display:none}\n.panel.on{display:block;animation:rise .35s both}\n.item{padding:11px 2px;border-bottom:1px solid var(--line);font-size:13px;line-height:1.5}\n.item:last-child{border-bottom:none}\n.item .sub{color:var(--t1);font-size:11px;margin-top:2px}\n.chip{display:inline-block;font-size:9.5px;font-weight:800;border-radius:5px;padding:2px 6px;\n  background:rgba(245,181,68,.14);color:var(--gold);margin-right:6px;letter-spacing:.05em}\n.chip.red{background:rgba(255,45,79,.14);color:#ff97a8}\n.empty{color:var(--t2);font-size:12.5px;padding:16px 2px;text-align:center}\n/* performance detail rows */\n.kv{display:flex;justify-content:space-between;padding:9px 2px;border-bottom:1px solid var(--line);font-size:13px}\n.kv:last-child{border-bottom:none}\n.kv span{color:var(--t1)} .kv b{font-variant-numeric:tabular-nums}\n#jSwitch{display:flex;gap:6px;margin-bottom:10px}\n#jSwitch div{flex:1;text-align:center;font-size:11px;font-weight:700;padding:7px;border-radius:9px;\n  border:1px solid var(--line);color:var(--t1);background:var(--card)}\n#jSwitch div.on{color:#fff;background:rgba(255,45,79,.13);border-color:rgba(255,45,79,.4)}\n#liveDot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--up);margin-right:6px;animation:pulse 1.6s ease-in-out infinite}@keyframes pulse{50%{opacity:.25}}\n#err{position:fixed;bottom:10px;left:16px;right:16px;background:rgba(255,69,96,.14);border:1px solid rgba(255,69,96,.4);\n  color:#ffb4be;font-size:11.5px;padding:8px 12px;border-radius:10px;display:none;z-index:9}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <div id="hero" class="rise">\n    <div id="brand">APEX <b>TERMINAL</b></div>\n    <div id="statusLine">👀 Watching <b>—</b></div>\n    <div id="balRow">\n      <div><div id="balLbl" style="font-size:9.5px;font-weight:800;letter-spacing:.14em;color:var(--t2);margin-bottom:3px">EQUITY · LIVE</div><div id="balV">$ —</div></div>\n      <div id="dayChip">today —</div>\n    </div>\n    <div id="balSub" style="margin-top:8px;font-size:12px;color:var(--t1);font-variant-numeric:tabular-nums">—</div><div id="badges"></div>\n  </div>\n\n  <div id="tiles" class="rise">\n    <div class="tile"><b id="tWr">—</b><span>Win rate</span></div>\n    <div class="tile"><b id="tPf">—</b><span>$ won / $ lost</span></div>\n    <div class="tile"><b id="tDd">—</b><span>Biggest dip</span></div>\n    <div class="tile"><b id="tSk">—</b><span>Skipped today</span></div>\n  </div>\n\n  <div class="card rise">\n    <div class="card-h"><b id="cSym">—</b><span id="cMeta"><i id="liveDot"></i>loading…</span></div>\n    <div id="chart"></div>\n    <div id="eqChart"></div>\n    <div id="pos"></div>\n  </div>\n\n  <div id="tabs" class="rise">\n    <div class="tab on" data-p="chart">📈 Chart</div>\n    <div class="tab" data-p="perf">💰 Stats</div>\n    <div class="tab" data-p="news">📰 News</div>\n    <div class="tab" data-p="journal">🧾 Journal</div>\n  </div>\n  <div class="panel on" id="p-chart"></div>\n  <div class="panel" id="p-perf"><div class="empty">Loading…</div></div>\n  <div class="panel" id="p-news"><div class="empty">Loading events…</div></div>\n  <div class="panel" id="p-journal">\n    <div id="jSwitch"><div class="on" data-j="trades">Trades</div><div data-j="skips">Skipped setups</div></div>\n    <div id="jTrades"><div class="empty">No trades yet.</div></div>\n    <div id="jSkips" style="display:none"><div class="empty">Nothing skipped yet today.</div></div>\n  </div>\n</div>\n<div id="err"></div>\n<script src="https://telegram.org/js/telegram-web-app.js"></script>\n<script src="https://unpkg.com/lightweight-charts@4.1.3/dist/lightweight-charts.standalone.production.js"></script>\n<script>\nconst tg = window.Telegram && Telegram.WebApp; if(tg){tg.ready();tg.expand();tg.setBackgroundColor(\'#07090f\');}\nconst initData = tg ? tg.initData : \'\';\nconst mk = (el,opts)=>LightweightCharts.createChart(el,Object.assign({\n  layout:{background:{color:\'transparent\'},textColor:\'#5b6472\',fontSize:10},\n  grid:{vertLines:{color:\'rgba(255,255,255,.04)\'},horzLines:{color:\'rgba(255,255,255,.04)\'}},\n  timeScale:{timeVisible:true,secondsVisible:false,borderColor:\'rgba(255,255,255,.08)\'},\n  rightPriceScale:{borderColor:\'rgba(255,255,255,.08)\'},crosshair:{mode:1}},opts||{}));\nconst chartEl=document.getElementById(\'chart\'), eqEl=document.getElementById(\'eqChart\');\nlet chart=null,series=null,eqChart=null,eqSeries=null;\ntry{\n  chart=mk(chartEl);\n  series=chart.addCandlestickSeries({upColor:\'#2fd575\',downColor:\'#ff4560\',\n    borderUpColor:\'#2fd575\',borderDownColor:\'#ff4560\',wickUpColor:\'#2fd575\',wickDownColor:\'#ff4560\'});\n  eqChart=mk(eqEl,{timeScale:{timeVisible:false}});\n  eqSeries=eqChart.addAreaSeries({lineColor:\'#ff2d4f\',lineWidth:2,\n    topColor:\'rgba(255,45,79,.25)\',bottomColor:\'rgba(255,45,79,0)\'});\n  new ResizeObserver(()=>{chart.applyOptions({width:chartEl.clientWidth,height:chartEl.clientHeight});\n    eqChart.applyOptions({width:eqEl.clientWidth,height:eqEl.clientHeight});}).observe(chartEl);\n}catch(e){console.error(\'chart lib unavailable\',e);}\nlet lines=[];\nfunction setLines(pos){if(!series)return;lines.forEach(l=>series.removePriceLine(l));lines=[];if(!pos)return;\n  const mkl=(p,c,t)=>{if(p)lines.push(series.createPriceLine({price:p,color:c,lineWidth:1,lineStyle:2,title:t}))};\n  mkl(pos.entryPrice,\'#eef1f6\',\'ENTRY\');mkl(pos.stopLoss||pos.sl,\'#ff4560\',\'SL\');mkl(pos.takeProfit||pos.tp,\'#2fd575\',\'TP\');}\ndocument.querySelectorAll(\'.tab\').forEach(t=>t.onclick=()=>{\n  document.querySelectorAll(\'.tab\').forEach(x=>x.classList.remove(\'on\'));\n  document.querySelectorAll(\'.panel\').forEach(x=>x.classList.remove(\'on\'));\n  t.classList.add(\'on\');document.getElementById(\'p-\'+t.dataset.p).classList.add(\'on\');\n  const perf = t.dataset.p===\'perf\';\n  chartEl.style.display = perf?\'none\':\'block\';\n  eqEl.style.display = perf?\'block\':\'none\';\n  document.getElementById(\'cSym\').textContent = perf?\'Equity curve\':lastSym;\n  setTimeout(()=>{if(eqChart)eqChart.timeScale().fitContent();},50);});\ndocument.querySelectorAll(\'#jSwitch div\').forEach(d=>d.onclick=()=>{\n  document.querySelectorAll(\'#jSwitch div\').forEach(x=>x.classList.remove(\'on\'));d.classList.add(\'on\');\n  document.getElementById(\'jTrades\').style.display=d.dataset.j===\'trades\'?\'block\':\'none\';\n  document.getElementById(\'jSkips\').style.display=d.dataset.j===\'skips\'?\'block\':\'none\';});\nconst esc=s=>String(s||\'\').replace(/[<>&]/g,c=>({\'<\':\'&lt;\',\'>\':\'&gt;\',\'&\':\'&amp;\'}[c]));\nconst money=v=>(v>=0?\'+$\':\'−$\')+Math.abs(v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});\nlet first=true,lastSym=\'—\';\nasync function refresh(){\n try{\n  const r=await fetch(\'/api/app/data?init=\'+encodeURIComponent(initData));\n  if(!r.ok)throw new Error(\'HTTP \'+r.status);\n  const d=await r.json();\n  document.getElementById(\'err\').style.display=\'none\';\n  lastSym=d.symbol.replace(\'_\',\'/\');\n  if(!document.querySelector(\'.tab[data-p="perf"]\').classList.contains(\'on\'))\n    document.getElementById(\'cSym\').textContent=lastSym;\n  document.getElementById(\'cMeta\').innerHTML=\'<i id="liveDot"></i>\'+(d.price?Number(d.price).toLocaleString(undefined,{maximumFractionDigits:5})+\' · \':\'\')+d.timeframe+\' · \'+(d.broker||\'\');\n  var _eq=(d.equityLive!=null?d.equityLive:(d.balance||0));var _bv=document.getElementById(\'balV\');var _prev=window.__eq;window.__eq=_eq;_bv.textContent=\'$\'+_eq.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});if(_prev!=null&&_eq!==_prev){_bv.classList.remove(\'up\',\'dn\');void _bv.offsetWidth;_bv.classList.add(_eq>_prev?\'up\':\'dn\');setTimeout(function(){_bv.classList.remove(\'up\',\'dn\');},600);}var _fl=(d.floatingPnl||0);var _bs=document.getElementById(\'balSub\');if(_bs){_bs.innerHTML=\'Balance $\'+(d.balance||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+(d.position?\' · <span class=\"\'+(_fl>=0?\'pnl-up\':\'pnl-dn\')+\'\">Floating \'+money(_fl)+\'</span>\':\'\');}\n  const st=d.stats||{},td=st.today||{};\n  const chip=document.getElementById(\'dayChip\');\n  chip.textContent=\'today \'+money(td.netPnl||0)+\' · \'+(td.trades||0)+\' trades\';\n  chip.className=(td.netPnl||0)<0?\'neg\':\'\';\n  const sl=document.getElementById(\'statusLine\');\n  if(d.position){\n    const up=(d.floatingPnl||0)>=0;\n    sl.innerHTML=(up?\'🟢 In a \':\'🔴 In a \')+(d.position.side===\'BUY\'?\'BUY\':\'SELL\')+\' on <b>\'+esc(lastSym)+\'</b> — \'+(up?\'up $\':\'down $\')+Math.abs(d.floatingPnl||0).toFixed(2);\n  }else{\n    sl.innerHTML=\'👀 Watching <b>\'+esc(lastSym)+\'</b> — no position, waiting for a setup\';\n  }\n  const bparts=[];\n  if(d.mode)bparts.push(d.mode);\n  if(d.strategy)bparts.push(d.strategy);\n  if(d.regime&&d.regime.regime)bparts.push(d.regime.regime.charAt(0).toUpperCase()+d.regime.regime.slice(1)+\' market\');\n  if(d.sessions&&d.sessions.length)bparts.push(d.sessions.join(\' + \'));\n  document.getElementById(\'badges\').innerHTML=bparts.map(esc).join(\'  ·  \');\n  document.getElementById(\'tWr\').textContent=st.winRate!=null?st.winRate.toFixed(0)+\'%\':\'—\';\n  document.getElementById(\'tPf\').textContent=st.profitFactor!=null?st.profitFactor:\'—\';\n  document.getElementById(\'tDd\').textContent=st.maxDrawdownPct!=null?st.maxDrawdownPct.toFixed(1)+\'%\':\'—\';\n  document.getElementById(\'tSk\').textContent=td.skips!=null?td.skips:\'0\';\n  if(series&&d.candles&&d.candles.length){\n    series.setData(d.candles);if(first){chart.timeScale().fitContent();first=false;}}\n  if(eqSeries&&d.equity&&d.equity.length){\n    eqSeries.setData(d.equity.map((p,i)=>({time:i,value:p.value})));}\n  setLines(d.position);\n  const pos=document.getElementById(\'pos\');\n  if(d.position){const p=d.position,dir=p.side===\'BUY\'?\'🟢 LONG\':\'🔴 SHORT\';\n    pos.style.display=\'block\';\n    pos.innerHTML=\'<span class="lg">\'+dir+\' \'+esc(lastSym)+\'</span>\'+\n      (p.pnlPips!=null?\' · <span class="\'+(p.pnlPips>=0?\'pnl-up\':\'pnl-dn\')+\'">\'+(p.pnlPips>=0?\'+\':\'\')+p.pnlPips+\' pips\'+(p.pnlUsd!=null?\' (\'+money(p.pnlUsd)+\')\':\'\')+\'</span>\':\'\')+\n      \'<div class="grid"><div>Entry<b>\'+(p.entryPrice||\'—\')+\'</b></div>\'+\n      \'<div>Stop<b>\'+((p.stopLoss||p.sl)||\'—\')+\'</b></div>\'+\n      \'<div>Target<b>\'+((p.takeProfit||p.tp)||\'—\')+\'</b></div></div>\';\n  }else pos.style.display=\'none\';\n  const perf=document.getElementById(\'p-perf\');\n  if(st.trades){\n    perf.innerHTML=\n      \'<div class="kv"><span>Closed trades</span><b>\'+st.trades+\' (\'+st.wins+\'W / \'+st.losses+\'L)</b></div>\'+\n      \'<div class="kv"><span>Net P&L</span><b class="\'+(st.netPnl>=0?\'pnl-up\':\'pnl-dn\')+\'">\'+money(st.netPnl)+\'</b></div>\'+\n      \'<div class="kv"><span>$ won per $ lost</span><b>\'+(st.profitFactor!=null?st.profitFactor:\'—\')+\'</b></div>\'+\n      \'<div class="kv"><span>Average win / loss</span><b>\'+money(st.avgWin)+\' / \'+money(st.avgLoss)+\'</b></div>\'+\n      \'<div class="kv"><span>Best / worst trade</span><b>\'+money(st.best)+\' / \'+money(st.worst)+\'</b></div>\'+\n      \'<div class="kv"><span>Biggest dip from peak</span><b>\'+st.maxDrawdownPct.toFixed(1)+\'%</b></div>\';\n  }else perf.innerHTML=\'<div class="empty">No closed trades yet — stats build as the bot works.</div>\';\n  const nv=document.getElementById(\'p-news\');\n  const todayEv=d.newsToday||[];\n  if(todayEv.length){\n    nv.innerHTML=todayEv.map(e=>{const past=e.mins<=0,am=Math.abs(e.mins),h=Math.floor(am/60),m=am%60;\n      const when=past?((h?h+\'h \':\'\')+m+\'m ago\'):(\'in \'+(h?h+\'h \':\'\')+m+\'m\');\n      return \'<div class="item"><span class="chip\'+(past?\' red\':\'\')+\'">\'+esc(e.currency)+\'</span><b>\'+esc(e.title)+\'</b>\'+\n        \'<div class="sub">\'+(past?\'Released \':\'\')+when+\' · high impact\'+(past?\'\':\' — the bot stands aside around it\')+\'</div></div>\';}).join(\'\');\n  }else if(d.events&&d.events.length){\n    nv.innerHTML=d.events.map(e=>{const h=Math.floor(e.in_min/60),m=e.in_min%60;\n      return \'<div class="item"><span class="chip">\'+esc(e.currency)+\'</span><b>\'+esc(e.title)+\'</b>\'+\n        \'<div class="sub">in \'+(h?h+\'h \':\'\')+m+\'m · high impact — the bot stands aside around it</div></div>\';}).join(\'\');\n  }else nv.innerHTML=\'<div class="empty">No high-impact events today — clear runway. ✅</div>\';\n  const jt=document.getElementById(\'jTrades\');\n  if(d.trades&&d.trades.length){\n    jt.innerHTML=d.trades.map(t=>{const pnl=t.netPnl;\n      return \'<div class="item"><b>\'+esc(t.action||\'\')+\'</b> \'+esc((t.symbol||\'\').replace(\'_\',\'/\'))+\n        (t.price?\' @ \'+t.price:\'\')+(pnl!=null?\' · <span class="\'+(pnl>=0?\'pnl-up\':\'pnl-dn\')+\'">\'+money(pnl)+\'</span>\':\'\')+\n        \'<div class="sub">\'+esc(t.time||\'\')+(t.reasoning?\' — \'+esc(t.reasoning):\'\')+\'</div></div>\';}).join(\'\');}\n  const js=document.getElementById(\'jSkips\');\n  if(d.skips&&d.skips.length){\n    js.innerHTML=d.skips.map(k=>\'<div class="item"><span class="chip red">SKIP</span>\'+esc(k.reason)+\n      \'<div class="sub">\'+esc(k.time||\'\')+\'</div></div>\').join(\'\');}\n }catch(e){const el=document.getElementById(\'err\');el.style.display=\'block\';el.textContent=\'Reconnecting… (\'+e.message+\')\';}\n}\nrefresh();setInterval(refresh,2000);\n</script>\n</body>\n</html>'

GUIDE_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">\n<title>Apex — How it works</title>\n<script src="https://telegram.org/js/telegram-web-app.js"></script>\n<style>\n:root{--bg:#07090f;--card:rgba(255,255,255,.05);--line:rgba(255,255,255,.09);\n  --t0:#eef1f6;--t1:#a6adba;--t2:#5b6472;--acc:#ff2d4f;--acc2:#ff5c74;--up:#2fd575;--gold:#f5b544}\n*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nbody{background:var(--bg);color:var(--t0);font-family:-apple-system,\'SF Pro Display\',system-ui,sans-serif;\n  line-height:1.55;padding-bottom:40px}\nbody::before{content:\'\';position:fixed;inset:0;pointer-events:none;z-index:0;\n  background:radial-gradient(80% 30% at 50% -5%,rgba(255,45,79,.20),transparent 72%)}\n.wrap{position:relative;z-index:1;max-width:620px;margin:0 auto;padding:0 18px}\n@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}\n.hero{padding:34px 4px 10px;text-align:center;animation:rise .5s both}\n.hero .em{font-size:40px}\nh1{font-size:27px;font-weight:800;letter-spacing:-.02em;margin:10px 0 8px;line-height:1.12}\nh1 .g{background:linear-gradient(115deg,var(--acc),var(--acc2));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}\n.hero p{color:var(--t1);font-size:15px;max-width:420px;margin:0 auto}\n.sec{font-size:12px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:var(--t2);margin:28px 6px 4px}\n.step{display:flex;gap:14px;align-items:flex-start;background:linear-gradient(165deg,rgba(255,255,255,.06),rgba(255,255,255,.02));\n  border:1px solid var(--line);border-radius:18px;padding:16px;margin:10px 0;backdrop-filter:blur(12px);animation:rise .5s both}\n.num{flex-shrink:0;width:38px;height:38px;border-radius:12px;background:linear-gradient(150deg,var(--acc),#b31832);\n  color:#fff;font-weight:800;font-size:17px;display:flex;align-items:center;justify-content:center;box-shadow:0 6px 18px rgba(255,45,79,.4)}\n.step h3{font-size:16.5px;font-weight:800;margin-bottom:3px}\n.step p{color:var(--t1);font-size:14px}\n.step p b{color:var(--t0)}\n.big{background:linear-gradient(165deg,rgba(255,45,79,.10),rgba(255,255,255,.02));border:1px solid rgba(255,45,79,.22);\n  border-radius:18px;padding:18px;margin:12px 0;text-align:center;animation:rise .5s both}\n.big .em{font-size:30px}\n.big h3{font-size:17px;font-weight:800;margin:6px 0 4px}\n.big p{color:var(--t1);font-size:14px}\n.two{display:flex;gap:10px;margin:10px 0}\n.two>div{flex:1;border-radius:16px;padding:14px;border:1px solid var(--line)}\n.two .test{background:rgba(47,213,117,.08);border-color:rgba(47,213,117,.25)}\n.two .live{background:rgba(255,45,79,.08);border-color:rgba(255,45,79,.25)}\n.two h4{font-size:14.5px;font-weight:800;margin-bottom:3px}\n.two p{font-size:12.5px;color:var(--t1)}\n.faq{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:6px 16px;margin:8px 0}\n.faq .q{font-weight:700;font-size:14.5px;padding:11px 0 3px}\n.faq .a{color:var(--t1);font-size:13.5px;padding-bottom:11px;border-bottom:1px solid var(--line)}\n.faq .a:last-child{border-bottom:none}\n.safe{display:flex;gap:12px;align-items:flex-start;background:rgba(47,213,117,.07);border:1px solid rgba(47,213,117,.22);\n  border-radius:16px;padding:15px;margin:12px 0}\n.safe .em{font-size:22px}\n.safe b{color:var(--up)}\n.safe p{font-size:13.5px;color:var(--t1)}\n.close{display:block;width:100%;text-align:center;background:linear-gradient(150deg,var(--acc),#b31832);color:#fff;\n  font-weight:800;font-size:16px;border:none;border-radius:15px;padding:16px;margin-top:24px;cursor:pointer;\n  box-shadow:0 10px 30px rgba(255,45,79,.35)}\n.foot{color:var(--t2);font-size:11.5px;text-align:center;margin-top:22px}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <div class="hero">\n    <div class="em">🤖</div>\n    <h1>Your bot trades for you.<br><span class="g">You just watch.</span></h1>\n    <p>No PC. No installs. No trading knowledge needed. Everything happens right here in Telegram. Here\'s the whole thing 👇</p>\n  </div>\n\n  <div class="sec">Start in 3 taps</div>\n  <div class="step"><div class="num">1</div><div><h3>Connect your account</h3><p>Tap <b>Set up my bot</b> and log in to your broker. The bot connects to <b>your own</b> account — and it can <b>never</b> take your money out, only trade.</p></div></div>\n  <div class="step"><div class="num">2</div><div><h3>Choose (or let the bot choose)</h3><p>Pick what to trade — or tap <b>🤖 Auto-Pilot</b> and the bot finds the best trades itself across gold, currencies and more.</p></div></div>\n  <div class="step"><div class="num">3</div><div><h3>It\'s ON — done</h3><p>The bot watches the market 24/5 and opens trades on its own. You get a message every time it does something, in plain words.</p></div></div>\n\n  <div class="big"><div class="em">🟢🔴</div><h3>One button controls everything</h3><p>Under every message there\'s a button: <b>▶️ Turn ON</b> to trade, <b>⏸ Turn OFF</b> to pause. That\'s the only control you ever need.</p></div>\n\n  <div class="sec">Test first, then go real</div>\n  <div class="two">\n    <div class="test"><h4>🧪 Demo</h4><p>Test the bot risk-free on a demo account. Start here.</p></div>\n    <div class="live"><h4>🔴 Live</h4><p>Real money. Switch when you\'re confident.</p></div>\n  </div>\n\n  <div class="safe"><div class="em">🛡️</div><div><b>You\'re protected.</b><p>Every trade gets a safety stop placed at your broker automatically. A daily loss limit stops the bot if things go wrong. Your money stays yours — the bot can trade, never withdraw.</p></div></div>\n\n  <div class="sec">Common questions</div>\n  <div class="faq">\n    <div class="q">It\'s ON but not trading — is it broken?</div>\n    <div class="a">No! It only opens trades when it spots a good one, and waits patiently for them. Quiet market = no trades. That\'s smart, not broken.</div>\n    <div class="q">Do I need to know trading?</div>\n    <div class="a">No. Tap Auto-Pilot and the bot decides everything. You just watch the messages.</div>\n    <div class="q">Where do I see my money?</div>\n    <div class="a">Send <b>/status</b> anytime, or tap <b>📊 Open Terminal</b> for a live screen with your chart, trades and balance.</div>\n    <div class="q">Can I stop it whenever I want?</div>\n    <div class="a">Yes — tap ⏸ Turn OFF. Nothing new opens; any running trade stays protected by its safety stop.</div>\n  </div>\n\n  <div class="sec">Your controls</div>\n  <div class="faq">\n    <div class="q">/start · /stop</div>\n    <div class="a">Turn the bot ON or OFF. When OFF, no new trades open. Open positions keep their safety stop.</div>\n    <div class="q">/status</div>\n    <div class="a">See your current position, balance, and what the bot is doing right now.</div>\n    <div class="q">/terminal</div>\n    <div class="a">Open the live dashboard — chart, equity curve, stats, and trade journal in one screen.</div>\n    <div class="q">/report</div>\n    <div class="a">Full trade journal with profit/loss breakdown for every trade.</div>\n    <div class="q">/buy · /sell · /close</div>\n    <div class="a">Manually open a BUY or SELL trade, or close your current position.</div>\n    <div class="q">/strategy</div>\n    <div class="a">Pick how the bot trades: Auto (adapts to market), Mean Reversion, Trend Following, or Breakout.</div>\n    <div class="q">/risk 1</div>\n    <div class="a">Set risk per trade (0.5–10%). Lower = safer, higher = more aggressive.</div>\n    <div class="q">/copilot on</div>\n    <div class="a">The bot asks you before opening each trade. You approve or skip.</div>\n    <div class="q">/autopilot on</div>\n    <div class="a">The bot picks the best instruments to trade automatically.</div>\n    <div class="q">/ctrader</div>\n    <div class="a">Connect or switch your cTrader broker account.</div>\n  </div>\n\n  <button class="close" onclick="if(window.Telegram&&Telegram.WebApp)Telegram.WebApp.close()">Got it — let\'s set it up →</button>\n  <div class="foot">Apex Forex Bot · Trading involves risk · Educational, not financial advice · You control your account.</div>\n</div>\n<script>\nconst tg=window.Telegram&&Telegram.WebApp; if(tg){tg.ready();tg.expand();tg.setBackgroundColor(\'#07090f\');}\ndocument.querySelectorAll(\'.step,.big,.two,.safe,.faq\').forEach((c,i)=>{c.style.animationDelay=(i*0.05)+\'s\';});\n</script>\n</body>\n</html>'


def _asset_swaps(html: str) -> str:
    """Rewrite the asset-class-specific wording in the shared Mini-App HTML so
    the crypto build reads 'Bitcoin, Ethereum … 24/7' and the forex build keeps
    'gold, currencies … 24/5'. Driven by config so one HTML serves both."""
    from apex import config as cfg
    out = html.replace("Apex Forex Bot", cfg.BOT_NAME)
    if getattr(cfg, "MARKET_24_7", False):
        out = out.replace("24/5", "24/7")
        out = out.replace("across gold, currencies and more",
                          "across Bitcoin, Ethereum, Solana and more")
    out = _broker_gate_swaps(out)
    return out


def _broker_gate_swaps(html: str) -> str:
    """While the live-broker growth-phase gate is on (see
    ctrader_oauth.broker_gate_reason), a demo account never unlocks free
    access — so the guide shouldn't tell a new client to 'start' on one."""
    import os
    if os.getenv("REQUIRE_LIVE_FP_MARKETS", "true").strip().lower() in ("0", "false", "no"):
        return html
    broker = (os.getenv("REQUIRED_BROKER_NAME", "").strip() or "FP Markets")
    out = html.replace("Test first, then go real", f"Connect your live {broker} account")
    out = out.replace(
        '<div class="test"><h4>\U0001f9ea Demo</h4><p>Test the bot risk-free on a demo account. Start here.</p></div>',
        '<div class="test"><h4>\U0001f9ea Demo</h4><p>For testing only — free access needs a live account.</p></div>')
    out = out.replace(
        "<p>Real money. Switch when you're confident.</p>",
        f"<p>Required for free access — live {broker} account. Start here.</p>")
    return out


def guide_html() -> str:
    """The How-it-works guide, asset-class aware."""
    return _asset_swaps(GUIDE_HTML)


def terminal_html() -> str:
    """The live terminal Mini App, asset-class aware."""
    return _asset_swaps(HTML)
